final class BankAccount{private$publicId,$tenantId,$name,$accountReference,$iban,$currency,$active;public function __construct(string$publicId,TenantId$tenantId,string$name,string$accountReference,Currency$currency,string$iban='',bool$active=true){$publicId=trim($publicId);$name=trim($name);$accountReference=strtoupper(preg_replace('/\s+/','',$accountReference));$iban=strtoupper(preg_replace('/\s+/','',$iban));if($publicId===''||strlen($publicId)>64||$name===''||strlen($name)>128||$accountReference===''||strlen($accountReference)>64){throw new \InvalidArgumentException('Bankrekening vereist geldige ids en naam.');}if(preg_match('/^[A-Z0-9._-]+$/D',$accountReference)!==1){throw new \InvalidArgumentException('Bankrekeningreferentie bevat ongeldige tekens.');}if($iban!==''&&!CounterpartySnapshot::validIban($iban)){throw new \InvalidArgumentException('Bankrekening heeft een ongeldig IBAN.');}$this->publicId=$publicId;$this->tenantId=$tenantId;$this->name=$name;$this->accountReference=$accountReference;$this->currency=$currency;$this->iban=$iban;$this->active=$active;}public function getPublicId():string{return$this->publicId;}public function getTenantId():TenantId{return$this->tenantId;}public function getName():string{return$this->name;}public function getAccountReference():string{return$this->accountReference;}public function getIban():string{return$this->iban;}public function getCurrency():Currency{return$this->currency;}public function isActive():bool{return$this->active;}}
